// Reject anything that is not this deployment.
// N8N_WEBHOOK_SECRET must match the backend's.
const crypto = require('crypto');
const secret = $env.JAL_SAKSHI_WEBHOOK_SECRET;
const raw = $input.first().binary ? Buffer.from($input.first().binary.data.data, 'base64') : Buffer.from(JSON.stringify($input.first().json.body ?? $input.first().json));
const presented = ($input.first().json.headers?.['x-jalsakshi-signature'] ?? '').trim();
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(raw).digest('hex');
if (!secret || presented !== expected) {
  throw new Error('signature rejected');
}
return [{ json: $input.first().json.body ?? $input.first().json }];

// Pull the work-order code out of the message the crew is replying to.
// The code is quoted in every dispatch as 'Work Order: WO-001'.
const message = $json.message ?? {};
const quoted = message.reply_to_message?.text ?? '';
const match = quoted.match(/Work Order:\s*(WO-\d+)/i) || (message.text ?? '').match(/(WO-\d+)/i);
if (!match) {
  // Not every message to the bot is a field update — people say 'hi', and the
  // bot sits in a group where humans talk to each other. A message that names
  // no work order is not an error, it is simply not ours: end the branch
  // quietly rather than filling the execution log with red.
  return [];
}
return [{ json: {
  event: 'FIELD_UPDATE',
  work_order_id: match[1],
  sender: message.from?.username || message.from?.first_name || 'telegram-user',
  message: message.text ?? '',
  chat_id: String(message.chat?.id ?? ''),
  external_message_id: String(message.message_id ?? ''),
} }];
